export type BrandLogoName = keyof typeof brandLogos;

const symbolId = (name: BrandLogoName) => `brand-logo-${name}`;

/**
 * Defines each logo once as an SVG symbol, so pages that show a logo several times (like the
 * looping marquee) do not repeat its path data. Render it once per page, before any BrandLogo.
 */
export function BrandLogoSprite({ names }: { names: readonly BrandLogoName[] }) {
  return (
    <svg aria-hidden="true" focusable="false" width="0" height="0" className="absolute">
      {names.map((name) => {
        const logo: BrandLogoData = brandLogos[name];
        return (
          <symbol key={name} id={symbolId(name)} viewBox={logo.viewBox}>
            {logo.paths.map((path) => (
              <path key={path.d} d={path.d} fill={path.fill} stroke={path.stroke} />
            ))}
          </symbol>
        );
      })}
    </svg>
  );
}

/** One logo in its brand color, drawn from the sprite. Decorative: name the tool in text next to it. */
export function BrandLogo({ name, className }: { name: BrandLogoName; className?: string }) {
  const logo: BrandLogoData = brandLogos[name];
  const style = {
    '--logo-light': logo.light ?? 'currentColor',
    '--logo-dark': logo.dark ?? 'currentColor',
  } as CSSProperties;
  return (
    <svg aria-hidden="true" focusable="false" className={cn('brand-logo', className)} style={style}>
      <use href={`#${symbolId(name)}`} />
    </svg>
  );
}
